#include "Esp32.h"
#include "main.h"
// External USART1 handle generated by STM32CubeMX
extern UART_HandleTypeDef huart1;

void ESP32_Init(void)
{
    // Clear any overrun or noise flags on the USART1 receiver line
    __HAL_UART_CLEAR_OREFLAG(&huart1);
}

uint8_t ESP32_ReadToken(uint8_t *token, uint32_t timeout_ms)
{
    // Receive a single 1-byte command token from ESP32-S3
    if (HAL_UART_Receive(&huart1, token, 1, timeout_ms) == HAL_OK)
    {
        return 1; // Token successfully received
    }
    return 0; // Timeout or no byte waiting
}

void ESP32_SendCommand(uint8_t cmd)
{
    // Send a single character/command downstream to the ESP32-S3
    HAL_UART_Transmit(&huart1, &cmd, 1, 100);
}
